using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Notifications.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Notifications.Queries.GetNotifications;public sealed class GetNotificationsQueryHandler(INotificationRepository repository):IRequestHandler<GetNotificationsQuery,Result<IReadOnlyList<NotificationDto>>>{public async Task<Result<IReadOnlyList<NotificationDto>>>Handle(GetNotificationsQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<NotificationDto>>((await repository.GetAllAsync(request.UserId,request.IsRead,cancellationToken)).Select(NotificationDto.FromEntity).ToList());}
